-- Avatar bodies the starter list (0012) lacks, and the other forms in which listings write an existing avatar's name:
-- short forms (クマリ for ひきくまりのクマリ), each character of a listing that sells several (彼方 and 此方). A new row
-- lists as aliases the full forms its name leaves out (蠱惑のミダリス). The rule and the measurements behind each row are
-- in the pull request that added this file. Avatar names are never translated.

update avatars a set aliases = v.aliases from (values
  ('avzomend', array['ゾメ']::text[]),
  ('inaba', array['椎名', '狐雨']::text[]),
  ('isanai-nuku', array['イサナイ']::text[]),
  ('kanata-konata', array['彼方', '此方']::text[]),
  ('kipfel', array['きぷふぇる']::text[]),
  ('kumaly', array['クマリ', 'Kumari']::text[]),
  ('leeme-reeva', array['Leeme', 'Reeva']::text[]),
  ('mafuyu', array['まふゆ']::text[]),
  ('manuka', array['まぬか']::text[]),
  ('milk-sugar', array['みるくらて', 'しゅがーらて']::text[]),
  ('misaki', array['海咲']::text[]),
  ('nagiya-ruri', array['凪夜瑠璃']::text[]),
  ('new-necomaid', array['NecoMaid']::text[]),
  ('pon-chune', array['ぽんちゅね']::text[]),
  ('puma-the-puma', array['ぷまちゃん']::text[]),
  ('rearalice', array['リアアリス']::text[]),
  ('retinia-retinietta', array['レティニア', 'レティニエッタ']::text[]),
  ('rurune', array['るるね']::text[]),
  ('selestia', array['せれすてぃあ']::text[]),
  ('shinano', array['シナノ']::text[]),
  ('shinra', array['しんら']::text[]),
  ('shizuku-san', array['びしょぬれのしずく']::text[]),
  ('sii-phi', array['シィファイ']::text[]),
  ('yugi-miyo', array['ユギミヨ', 'ユギ', 'ミヨ']::text[]),
  ('yuuko-san', array['幽狐族のお姉']::text[])
) as v(slug, aliases) where a.slug = v.slug;

-- body listings the starter rows lacked
update avatars a set avatar_item_id = v.id from (values
  ('byrons', 8829002),
  ('kirisame', 8596249),
  ('kuroki', 8822547),
  ('latte', 8733827),
  ('melvii', 8727844),
  ('miro', 7413817),
  ('misaki', 8325804),
  ('oriefia', 8600821),
  ('ronferin', 8721165),
  ('ruu', 5767548)
) as v(slug, id) where a.slug = v.slug and a.avatar_item_id is null;

on conflict (slug) do nothing;

-- A body listing names its avatar, as the starter rows' listings do (VRCatalogue's "supported avatar"); the avatars
-- view's "Known avatars only" reads it. Crawls and enrichment never write these columns.
update items i set avatar_slug = a.slug, supported = true, gender = coalesce(i.gender, a.gender)
from avatars a
where i.id = a.avatar_item_id and i.avatar_slug is null;
